from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode


def apply_rewrite_rules(rules, urls):
    results = []

    for url_str in urls:
        parsed_url = urlparse(url_str)
        matched = False
        new_url_str = url_str

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            is_match = False

            # 1. Check match types
            if match_type == "path_prefix":
                if parsed_url.path.startswith(match_value):
                    is_match = True

            elif match_type == "host":
                host = parsed_url.hostname or ""
                if match_value.startswith("*."):
                    suffix = match_value[1:]  # e.g., ".example.com"
                    # Must be a proper subdomain, not the domain itself
                    if host.endswith(suffix) and host != match_value[2:]:
                        is_match = True
                else:
                    if host == match_value:
                        is_match = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    is_match = True

            # 2. If matched, apply the action
            if is_match:
                matched = True

                if action == "block":
                    new_url_str = None
                    break

                elif action == "strip_prefix":
                    path = parsed_url.path
                    if path.startswith(action_value):
                        path = path[len(action_value) :]
                    if not path.startswith("/"):
                        path = "/" + path
                    # Reconstruct URL
                    parts = list(parsed_url)
                    parts[2] = path  # index 2 is path
                    new_url_str = urlunparse(parts)

                elif action == "redirect_host":
                    # action_value is the new host
                    # We need to replace the host part in netloc while preserving port if present
                    netloc = action_value
                    if parsed_url.port:
                        netloc = f"{netloc}:{parsed_url.port}"

                    parts = list(parsed_url)
                    parts[1] = netloc  # index 1 is netloc
                    new_url_str = urlunparse(parts)

                elif action == "add_query_param":
                    # action_value is e.g. "key=value" or we can parse it
                    query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                    if "=" in action_value:
                        k, v = action_value.split("=", 1)
                        query_params.append((k, v))

                    new_query = urlencode(query_params)
                    parts = list(parsed_url)
                    parts[4] = new_query  # index 4 is query
                    new_url_str = urlunparse(parts)

                # Stop at the first matching rule
                break

        results.append(new_url_str)

    return results
